/** @jest-environment node */

const { extractEntries, APPLANGA_TAG } = require('../extractEntries');

describe('extractEntries', () => {
  it('exports APPLANGA_TAG as main', () => {
    expect(APPLANGA_TAG).toBe('main');
  });

  it('prefers draft values when enabled', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'homePage.title': { d: 'Draft', v: 'Release' },
          },
        },
      },
      true
    );

    expect(result['homePage.title']).toBe('Draft');
  });

  it('uses release values when draft is disabled', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'homePage.title': { d: 'Draft', v: 'Release' },
          },
        },
      },
      false
    );

    expect(result['homePage.title']).toBe('Release');
  });

  it('uses string entries directly', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'homePage.title': 'Plain',
          },
        },
      },
      false
    );

    expect(result['homePage.title']).toBe('Plain');
  });

  it('falls back to empty string for unknown entry shapes', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'homePage.title': null,
          },
        },
      },
      false
    );

    expect(result['homePage.title']).toBe('');
  });

  it('falls back to raw entry for objects without d or v', () => {
    const unknownEntry = { custom: 'value' };
    const result = extractEntries(
      {
        main: {
          entries: {
            'homePage.title': unknownEntry,
          },
        },
      },
      false
    );

    expect(result['homePage.title']).toBe(unknownEntry);
  });

  it('returns empty object when tag is missing', () => {
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
    expect(extractEntries({}, false)).toEqual({});
    warnSpy.mockRestore();
  });

  it('returns empty object when language data is null', () => {
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    expect(extractEntries(null, false)).toEqual({});
    expect(warnSpy).toHaveBeenCalledWith('⚠️  No language data found in API response');

    warnSpy.mockRestore();
  });

  it('skips branches without entries and warns when no valid branch exists', () => {
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    expect(
      extractEntries(
        {
          main: { metadata: 'only' },
          draft: null,
        },
        false
      )
    ).toEqual({});

    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('No entries found in language data')
    );
    warnSpy.mockRestore();
  });

  it('merges entries from multiple tag branches under the MFE namespace', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'hub-analytics.homePage.title': { v: 'Analytics Home' },
          },
        },
        'shared-components': {
          entries: {
            'shared-components.SurveyModal.title': { v: 'Survey' },
          },
        },
      },
      false
    );

    expect(result['hub-analytics.homePage.title']).toBe('Analytics Home');
    expect(result['hub-analytics.SurveyModal.title']).toBe('Survey');
    expect(result['SurveyModal.title']).toBeUndefined();
    expect(result['shared-components.SurveyModal.title']).toBeUndefined();
  });

  it('keeps MFE keys unchanged while nesting shared entries under the MFE namespace', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'hub-analytics.homePage.title': { v: 'Analytics Home' },
            'shared-components.SurveyModal.JourneyModal.title': { v: 'How was your experience?' },
          },
        },
      },
      false
    );

    expect(result['hub-analytics.homePage.title']).toBe('Analytics Home');
    expect(result['hub-analytics.SurveyModal.JourneyModal.title']).toBe('How was your experience?');
  });

  it('uses last value for duplicate keys across branches', () => {
    const result = extractEntries(
      {
        main: {
          entries: {
            'shared.key': { v: 'First' },
          },
        },
        analytics: {
          entries: {
            'shared.key': { v: 'Second' },
          },
        },
      },
      false
    );

    expect(result['shared.key']).toBe('Second');
  });
});
